// spec: .qa/e2e/specs/job-upgrade.md
// seed: tests/seed.hunter_plus.spec.ts
// Read-only: never click «לרכישה» / «הפעלת הקידום» (spends the free monthly counters). J-70 must stay active (KEEP data).
import { test, expect, Page } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const JOB = 'QA-AUTO 1020 C2 PLUS משרה 1';
const THRESHOLD = 'זמין למשרות עם שכר של ₪20,000 ומעלה';

async function openUpgrade(page: Page, title: string) {
  const card = page.getByRole('listitem').filter({ has: page.getByRole('heading', { name: title, exact: true }) });
  await expect(card).toHaveCount(1);
  const upgrade = page.getByRole('menuitem', { name: 'שדרוג משרה' });
  await expect(async () => {
    if (!(await upgrade.isVisible())) await card.getByRole('button', { name: 'פעולות משרה' }).click();
    await expect(upgrade).toBeVisible({ timeout: 2_000 });
  }).toPass({ timeout: 15_000 });
  await upgrade.click();
  const dialog = page.getByRole('dialog', { name: 'האם לשדרג את המשרה שלכם?' });
  await expect(dialog).toBeVisible();
  return dialog;
}

test.describe('Job upgrade popup — ₪20,000 threshold (#1396b6)', () => {
  test('Job at or above ₪20,000: promotion and distribution are available @desktop @prod-safe #1396b6', async ({ page }) => {
    // 1. «המשרות שלי» → J-70 → «•••» → «שדרוג משרה»
    await page.goto('/my-jobs');
    let dialog = await openUpgrade(page, JOB);

    // 2. Read the popup (no purchase / activation)
    await expect(dialog.getByText(JOB, { exact: true })).toBeVisible();
    const promo = dialog.getByRole('button', { name: /^קידום משרה/ });
    const dist = dialog.getByRole('button', { name: /^שירותי הפצה/ });

    await expect(promo).toBeEnabled();
    await expect(promo).toContainText('תווית “משרה חמה” והקפצה לראש הרשימה');
    await expect(promo).toContainText(/₪700/);
    await expect(promo).toContainText(/נותרו \d+ מתוך \d+ קידומים חינם החודש/);

    await expect(dist).toBeEnabled();
    await expect(dist).toContainText('הפצת המשרה שלכם לכל הד האנטרים באתר Hunters');
    await expect(dist).toContainText(/₪700/);
    await expect(dist).toContainText(/נותרו \d+ מתוך \d+ הפצות חינם החודש/);

    await expect(dialog.getByText(THRESHOLD)).toHaveCount(0);
    await expect(dialog.getByRole('radiogroup', { name: 'תקופת הקידום' })).toBeVisible();

    const counters = async () => [
      (await promo.innerText()).match(/נותרו \d+ מתוך \d+/)?.[0] ?? null,
      (await dist.innerText()).match(/נותרו \d+ מתוך \d+/)?.[0] ?? null,
    ];
    const before = await counters();

    // 3. «לא תודה» — popup closed
    await dialog.getByRole('button', { name: 'לא תודה', exact: true }).click();
    await expect(dialog).toBeHidden();

    // Counters unchanged: reopen, compare, close again with «לא תודה»
    dialog = await openUpgrade(page, JOB);
    await expect.poll(counters).toEqual(before);
    await dialog.getByRole('button', { name: 'לא תודה', exact: true }).click();
    await expect(dialog).toBeHidden();
  });
});
